declare @message nvarchar(4000)
select @message = ''
&VisibleFieldGridDetailShowing;
select @message as message
return






				select 'this._voucherCode='@@id';load$GridVoucherDetail$(this);&Clipboard.Loading;' as message
return




				select 'dispose$GridVoucherDetail$(this);' as message
return







function load$GridVoucherDetail$(g) {
	g.add_itemValueChanged(onChange$GridVoucherDetail$);
	g.add_onResponseComplete(on$GridVoucherDetail$ResponseComplete);
	g.add_commandEvent(on$GridVoucherDetail$ExecuteCommand);
	&FormulaExpression;
	udf$Detail$(g);
	udf$Detail$QuantityPrice(g);
}
function udf$Detail$QuantityPrice(g) {
 if (!g.get_element().parentForm._udfQuantityPrice) {
		udf$Field$(g, 'dvt');
		udf$Field$(g, 'so_luong');
		udf$Field$(g, 'gia_nt');
		udf$Field$(g, 'gia');
	}
}

function dispose$GridVoucherDetail$(g) {
	g.$a = null;
	try {g.remove_commandEvent(on$GridVoucherDetail$ExecuteCommand);} catch (ex) {}
	try {g.remove_itemValueChanged(onChange$GridVoucherDetail$);} catch (ex) {}
	try {g.remove_onResponseComplete(on$GridVoucherDetail$ResponseComplete);} catch (ex) {}
}

function onChange$GridVoucherDetail$(sender, eventArgs) {
	var o = eventArgs.get_object(), g = o.grid, f = g.get_element().parentForm, name = o.field.Name;
	var z = f.getItem('r30')._controlBehavior;
	switch (name) {
		case 'so_luong':
			g.validExpression(o, [g.$a.tien_nt_sl, g.$a.tien], [g.$a.t_tien_nt, g.$a.t_tien], [g.$a.t_tt_nt, g.$a.t_tt]);
			genTaxGrid(f, g, z);
			break;
		case 'gia_nt':
			g.validExpression(o, [g.$a.tien_nt_sl, g.$a.gia_tg, g.$a.tien], [g.$a.t_tien_nt, g.$a.t_tien], [g.$a.t_tt_nt, g.$a.t_tt], 'tien_nt');
			genTaxGrid(f, g, z);
			break;
		case 'gia':
			g.validExpression(o, [g.$a.tien_sl], [g.$a.t_tien], [g.$a.t_tt], 'tien');
			genTaxGrid(f, g, z);
			break;
		case 'tien_nt':
			if (f._calPrice && f._udfQuantityPrice) g.validExpression(o, [g.$a.gia_nt_sl, g.$a.gia_tg]);
			g.validExpression(o, [g.$a.tien], [g.$a.t_tien_nt, g.$a.t_tien], [g.$a.t_tt_nt, g.$a.t_tt]);
			genTaxGrid(f, g, z);
			break;
		case 'tien':
			if (f._calPrice && f._udfQuantityPrice) g.validExpression(o, [g.$a.gia_sl]);
			g.validExpression(o, null, [g.$a.t_tien], [g.$a.t_tt]);
			genTaxGrid(f, g, z);
			break;
		case 'dien_giai':
			if (z._rowCount == g._rowCount) {
				z._setItemValue(o.row, z._getColumnOrder('ten_vt'), o.value);
			}
			break;
		default:
			break;
	}
}

function on$GridVoucherDetail$RowChange(g, f) {
	g.executeAggregate([g.$a.t_tien_nt, g.$a.t_tien]);
	f.executeExpression([g.$a.t_tt_nt, g.$a.t_tt]);
	var z = f.getItem('r30')._controlBehavior;
	genTaxGrid(f, g, z);
}

function on$GridVoucherDetail$ResponseComplete(sender, e) {
	var g = e.object, context = e.type.Context, result = e.type.Result, o = e.type.Object, f = g.get_element().parentForm;
	switch (context) {
		&ESG.ScriptGridResponse;
		default:
			break;
	}
}
/* <flatten type="Javascript"> */
/* </flatten> */
function onChange$APDetail$Grid$loai_phi(o){
	var g = o.grid, f = g.get_element().parentForm;

	var row = o.row;
	if (g._getItemValue(row, g._getColumnOrder('loai_phi')) != 0){
		g._setItemValue(row, g._getColumnOrder('ma_phi'), '');
		g._setItemValue(row, g._getColumnOrder('ten_phi%l'), '');
	}
}

function on$GridVoucherDetail$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender, f = g.get_element().parentForm;
	var z = f.getItem('r30')._controlBehavior;
	switch (action) {
		&Clipboard.Event.Before;
		&Clipboard.Event.Before.Request;
		&Clipboard.Event.Before.Process;
		&Clipboard.Event.After;
		&Clipboard.Event.After.Process;
		case 'AfterRemoveRow':
			on$GridVoucherDetail$RowChange(g, f);
			break;
		case 'AfterCloneRow':
			g.setItemFieldValue('stt_rec0', e.type.Value, '');
			on$GridVoucherDetail$RowChange(g, f);
			break;
		case 'AfterMoveRow':
			genTaxGrid(f, g, z);
			break;
&GridExtraToolbarExecuteCommandScript;;
		case 'Check':
			&ESG.ScriptCheck;
			break;
		default:
			break;
	}
}

